import{_ as e,C as i,o as s,c as a,E as n,a4 as d}from"./chunks/framework.2-Vke5-n.js";const k=JSON.parse('{"title":"SMS設計ガイドライン","description":"","frontmatter":{"sidebarDepth":4,"title":"SMS設計ガイドライン","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"SMS,ショートメッセージ,スミッシング,RCS,電話番号"}]]},"headers":[],"relativePath":"documents/forMail/sms_guidelines.md","filePath":"documents/forMail/sms_guidelines.md"}'),r={name:"documents/forMail/sms_guidelines.md"};function p(o,t,h,g,y,c){const l=i("page-title");return s(),a("div",null,[n(l),t[0]||(t[0]=d(`<p>本ガイドラインは、SMS送信で考慮すべき設計事項と推奨案をまとめる。</p><p>位置づけ・適用範囲・用語・免責事項は <a href="./">Introduction</a> を参照。</p><p>メールと並び、ユーザーに直接情報を届けるチャネルにSMS（ショートメッセージサービス）がある。電話番号を宛先として、短いテキストメッセージを送受信でき、1990年代に携帯電話（2G/GSM）の標準機能として世界的に普及した。プッシュ通知で受信者の目に留まりやすく、開封率が高いため、以下のような即時性・確実性が求められる用途で活用されている。</p><ul><li><strong>本人認証・二要素認証（2FA）</strong>: ワンタイムパスワード（OTP）の送付</li><li><strong>重要通知</strong>: サービス約款の更新や重要な設定変更など</li><li><strong>緊急連絡</strong>: システムの緊急メンテナンス情報、災害時の安否確認</li></ul><div class="tip custom-block"><p class="custom-block-title">(コラム) 巧妙化するSMSの脅威と新しい潮流</p><p>SMSは本人性が高く安全なチャネルと見なされてきたが、近年は様々な脅威が増加しており、注意が必要である。</p><ul><li><strong>スミッシング（Smishing）</strong><ul><li>宅配業者・金融機関・公的機関などを装い、SMSで偽サイトへ誘導するフィッシング詐欺が増加</li><li>ユーザーが正規のSMSであると判断しやすい工夫（例：送信者IDの利用、URLのドメインの周知）が必要</li></ul></li><li><strong>偽基地局による中間者攻撃</strong><ul><li>偽の携帯電話基地局から付近の通信を傍受し、SMSの内容を盗聴したり、なりすましSMSを送信したりする「IMSIキャッチャー」という攻撃</li></ul></li></ul><p>上記のような脅威から、SMSの後継としてRCS（Rich Communication Services）が注目され、日本では「＋メッセージ」として提供されている。RCSでは、ブランドの公式マークの表示によるなりすましの軽減や、リッチなコンテンツの送受信が可能となる。RCSへ移行する流れもウォッチする必要がある。</p></div><h2 id="メールとの使い分け" tabindex="-1">メールとの使い分け <a class="header-anchor" href="#メールとの使い分け" aria-label="Permalink to &quot;メールとの使い分け&quot;">​</a></h2><p>SMSとメールは、下表のように特性が異なるため、要件に応じて使い分けることが求められる。「確実性と即時性」と「情報量と費用」でトレードオフ構造がある。</p><table tabindex="0"><thead><tr><th style="text-align:left;">観点</th><th style="text-align:left;">SMS</th><th style="text-align:left;">メール</th></tr></thead><tbody><tr><td style="text-align:left;">到達性</td><td style="text-align:left;">✅️100％近く届く</td><td style="text-align:left;">✅️適切に設計すれば到達率を高められる</td></tr><tr><td style="text-align:left;">開封率</td><td style="text-align:left;">✅️高い</td><td style="text-align:left;">⚠️迷惑メールフィルターや未読で読まれない確率が高い</td></tr><tr><td style="text-align:left;">即時性</td><td style="text-align:left;">✅️プッシュ通知されるため、すぐに気づかれやすい</td><td style="text-align:left;">⚠️ユーザーがメーラーを開くまで気づかれない</td></tr><tr><td style="text-align:left;">情報量</td><td style="text-align:left;">❌️ 少ない（通常全角70文字程度）。長文やファイル添付は不可</td><td style="text-align:left;">✅️多い。HTMLによる表現やファイル添付も可能</td></tr><tr><td style="text-align:left;">コスト</td><td style="text-align:left;">⚠️高い（1通あたり数円～十数円）</td><td style="text-align:left;">✅️安い</td></tr><tr><td style="text-align:left;">ユーザー体験</td><td style="text-align:left;">⚠️頻繁な通知は嫌われる傾向</td><td style="text-align:left;">✅️比較的許容されやすい。後で読み返す用途にも向く</td></tr></tbody></table><p>推奨は以下の通り。</p><ul><li>SMSの利用をなるべく下げる <ul><li>電話番号は個人情報として扱うことが一般的であり、収集の合意・暗号化など多くの配慮が必要である。利用しなくて済むなら、利用しない</li></ul></li><li>特に以下の場合は、SMSではなくメールの利用が向いている <ul><li>情報量が多く、記録として残す必要がある、利用規約の変更などの場面</li><li>PDFなどのファイルを添付する必要がある、領収書・請求書などの場合</li><li>コストを抑えて多くのユーザーに定期的に情報を届けたいメールマガジンなどの場面</li></ul></li><li>SMSを採用する場合は、運用費用を下げるため最小限とする <ul><li>ログインや決済時の本人確認や、ワンタイムパスワード送信など、セキュリティが「最優先」される場面</li><li>支払い期限の最終リマインドなど、ユーザーに気づいてほしい最終督促のような場面 <ul><li>SMSでも無視されることが多いとも考えられるが、開封率が高いことも事実である</li><li>SMSで通知したという事実が、後のサービス停止や法的措置へ移行する際にも正当性を補強する一因となる</li><li>「【重要】●●よりお支払いに関するご案内です。ご登録のメールアドレスをご確認ください」というように、メールやサービスログインへの誘導にすることで、コストを抑える</li></ul></li></ul></li></ul><h2 id="電話番号" tabindex="-1">電話番号 <a class="header-anchor" href="#電話番号" aria-label="Permalink to &quot;電話番号&quot;">​</a></h2><p>電話番号は多様な形式で表現される。</p><table tabindex="0"><thead><tr><th style="text-align:left;">形式</th><th style="text-align:left;">例</th><th style="text-align:left;">概要</th><th style="text-align:left;">特徴</th></tr></thead><tbody><tr><td style="text-align:left;">E.164形式</td><td style="text-align:left;"><code>+819012345678</code></td><td style="text-align:left;">ITU-T（国際電気通信連合）に標準化された国際的な形式</td><td style="text-align:left;">・ 「+」 「国コード」 「0を除いた国内番号」で構成される。<br>・記号やスペースを含まず、グローバルで番号を一意に識別できる。<br>・多くのクラウドサービスで標準的に採用されている</td></tr><tr><td style="text-align:left;">国内電話番号形式</td><td style="text-align:left;"><code>0X0-1234-5678</code></td><td style="text-align:left;">日本国内で一般的に利用される、市外局番などから始まる形式</td><td style="text-align:left;">・視認性のためにハイフンで区切られることが多い。<br>・国コードを含まないため、国際的なサービスでは利用できない。<br>・ハイフンの有無など、表記揺れが発生しやすい</td></tr></tbody></table><p>ユーザーのフォーム入力時にどの形式を要求するか、システムで保持する際にどの形式へ変換するかが考慮点となる。</p><p>推奨は以下の通り。</p><ul><li>ユーザー入力形式 <ul><li>グローバル利用が想定される場合は、E.164形式で入力する <ul><li>Googleがメンテナンスする <code>libphonenumber</code> といったライブラリの利用が便利である</li><li>このライブラリは正規化だけでなく、電話番号の妥当性検証（例: 日本の携帯電話番号として有効か）も可能である</li></ul></li><li>ただし、国内ユーザーのみ想定の場合は、「国内電話番号形式」を採用しても良い <ul><li>ユーザー入力時はハイフンの有無を許容する方が良い</li></ul></li></ul></li><li>E.164形式でDBに保存する <ul><li>標準化された仕様が存在する場合、それに従っておくことがベター（ライブラリやツールなどとの親和性も高い）</li><li>決済代行会社（Payment Gateway）やカード会社などでは、E.164形式で連携を求められる</li><li>国内電話番号形式で入力された場合も、バックエンドで正規化処理を行う</li></ul></li><li>ユーザーへの表示形式 <ul><li>入力と同様の形式にする</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">入力は柔軟に、データは厳格に</p><p>システム入力の設計原則に、「入力は柔軟に、データは厳格に」という言葉がある。電話番号入力はこれに従い、ハイフンの有無、全角・半角などを気にせず入力できるように、システム側でライブラリを用いて正規化することで、ユーザー体験を向上できる。</p></div><div class="tip custom-block"><p class="custom-block-title">E.164形式の入力フォーム</p><p>ユーザーにE.164形式 (+81X012345678) を直接入力させることは、離脱率を上げてしまう可能性が高く避けるべきである。そのため、<strong>「国選択」と「電話番号入力」を組み合わせる、</strong> <code>[ 日本 (+81) ▼ ] [ 9012345678 ]</code> <strong>の形式を推奨する。</strong></p><ul><li>国選択ドロップダウン:国を選択することで、国コード（例: <code>+81</code>）が自動設定される</li><li>電話番号入力欄: 国内番号（日本の場合は先頭の0を除いた 9012345678）を入力してもらう。プレースホルダーで例を示すと良い。また、090-XXXX-XXXX と入力しても、先頭の0をトリムする</li></ul></div><div class="tip custom-block"><p class="custom-block-title">国内電話番号形式の入力フォーム</p><p><code>[ 0X0 ] - [ 1234 ] - [ 5678 ]</code> という3つに分離した入力フォームには、オートコンプリートが効きにくいなどの課題がある。そのため、以下のように1つの入力フォームを利用することを推奨する。</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">label</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;phone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;電話番号&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">input</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tel&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;phone&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;phone&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  placeholder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;例: 09012345678&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  autocomplete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tel&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;ハイフンは不要です。&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></div><div class="tip custom-block"><p class="custom-block-title">国内電話番号形式で入力/表示する場合の具体的な変換フロー例</p><ol><li>ユーザーがフォームに <code>0X0-1234-5678</code> と入力する。</li><li>バックエンドは <code>libphonenumber</code> を利用してバリデーションと正規化を行う。</li><li>データベースにはE.164形式の <code>+81X012345678</code> として保存する。</li><li>マイページなどで表示する際は、再度ライブラリを使って国内形式の <code>0X0-1234-5678</code> にフォーマットして表示する。</li></ol></div><div class="warning custom-block"><p class="custom-block-title">電話番号は名寄せに使えないことが多い</p><p>複数のサービスを運営していると、サービス品質向上のためアカウント連携したい事が良くある。この時、電話番号が名寄せに使えるのではないか？ と思い浮かぶことがある。</p><p>しかし、電話番号は利用目的の合意ができていることを前提に収集が可能であり、目的変更には再同意が必要である。そのため、安易に電話番号で名寄せを行うと規約違反の可能性がある。また、同一人物が複数番号を持つ場合や、電話番号を家族で共有している場合も考えられ、誤った名寄せになる懸念もある。そのため、ユーザーの連携率に依存するが、Google、Apple IDなどのソーシャルログインで名寄せする案がベターである。</p></div><h2 id="電話番号の有効性" tabindex="-1">電話番号の有効性 <a class="header-anchor" href="#電話番号の有効性" aria-label="Permalink to &quot;電話番号の有効性&quot;">​</a></h2><p>ユーザーの入力した電話番号が、実際に使われている有効なものかを確認することで、SMS到達率の向上や、余計なコスト削減、不正利用の抑制などに繋げられる。確認方法は、以下の3つに大別される。</p><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">方式</th><th style="text-align:left;">説明</th><th style="text-align:left;">メリット</th><th style="text-align:left;">デメリット</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;"><strong>フォーマット検証</strong></td><td style="text-align:left;">電話番号の形式・桁数をチェック</td><td style="text-align:left;">実装が容易</td><td style="text-align:left;">番号が「現在使われているか」までは判断できない。例えば、解約済みの番号は有効と判定される</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;"><strong>サードパーティの電話番号検証API</strong></td><td style="text-align:left;">携帯電話ネットワークのデータベース（HLR: Home Location Register）に問い合わせ、電話番号が有効か、現在の利用キャリアを確認</td><td style="text-align:left;">ユーザーアクションが不要で、コストを抑えられる</td><td style="text-align:left;">Twilio Lookup、Numverify、Vonageの電話番号検証APIサービスの利用が必要。個人情報保護の観点から利用に注意が必要（個人情報保護法における委託になると考えられ、委託先の監督義務を負う）。番号が有効でも、実際にユーザーが所有しているかの確認ができない</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;"><strong>SMS送信による認証</strong></td><td style="text-align:left;">実際にSMSを送信し、本文に記載した認証コードの入力か、マジックリンクのクリックで疎通確認</td><td style="text-align:left;">最も確実</td><td style="text-align:left;">ユーザーアクションが必要。SMS送信コストが発生する</td></tr></tbody></table><p>3のSMS送信による認証は、以下の2パターンが考えられる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">認証コード（OTP）方式</th><th style="text-align:left;">マジックリンク方式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>説明</strong></td><td style="text-align:left;">ランダムなコード（例：6桁の数字）をSMSで送信し、ユーザーがフォーム入力</td><td style="text-align:left;">認証用のURL（マジックリンク）をSMSで送信し、ユーザーがクリックして認証を完了</td></tr><tr><td style="text-align:left;"><strong>ユーザー体験</strong></td><td style="text-align:left;">❌ ユーザーがコードをコピー&amp;ペースト、または手入力する手間が発生する<br> ✅多くのサービスで実用されており、広く浸透している</td><td style="text-align:left;">✅ リンクをタップするだけで認証が完了し、スムーズ<br> ⚠️リンクをタップすることに警戒心を持つユーザーも存在する</td></tr><tr><td style="text-align:left;"><strong>セキュリティ</strong></td><td style="text-align:left;">✅️標準的だが、フィッシングによるコードの窃取やSMSインターセプトのリスクは存在する</td><td style="text-align:left;">⚠️ トークンの適切な管理（有効期限、ワンタイム利用）が必須</td></tr><tr><td style="text-align:left;"><strong>実装の容易さ</strong></td><td style="text-align:left;">✅ 既存ライブラリを利用しやすい</td><td style="text-align:left;">❌ セキュアなトークン管理やURLの有効期限管理など、考慮事項が多く複雑になりがち</td></tr><tr><td style="text-align:left;"><strong>送信コスト</strong></td><td style="text-align:left;">❌ SMS送信コストが発生</td><td style="text-align:left;">❌ SMS送信コストが発生（URLが長くなると複数通分になる可能性も）</td></tr><tr><td style="text-align:left;"><strong>互換性</strong></td><td style="text-align:left;">✅ SMSが受信できる全てのデバイス（フィーチャーフォン含む）で利用可能</td><td style="text-align:left;">⚠️スマートフォンなど、SMSから直接ブラウザを開けるデバイスに限定される</td></tr></tbody></table><p>推奨は以下の通り。</p><ul><li>フォーマット検証はフォーム入力時に必須で行う</li><li>電話番号検証APIの利用は任意とする <ul><li>SMS送信数を減らすことの優先度が高いサービス特性の場合は、導入を検討する</li><li>電話番号検証APIを挟んでも、SMS送信による認証プロセスは必ず含める</li></ul></li><li>マジックリンク方式を第一に考える <ul><li>特に年齢層が上のユーザーは、OTP方式の場合に離脱率が高く、ユーザーサポートが大変になるため</li></ul></li><li>マジックリンクは、ユーザー操作がアプリの場合は、ディープリンク形式で送信する <ul><li>Webサービス経由の場合は、通常のリンク形式で送信する</li></ul></li><li>若者中心のサービスの場合は、認証コード（OTP）送信を採用しても良い <ul><li>デジタルネイティブ世代の多くがOTP方式に慣れている</li><li>Twilio、Vonage、Auth0など信頼できるプラットフォームがサポートし、導入が容易かつ業界標準的である <ul><li>ライブラリが対応しているので実装コストが低い</li></ul></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">OTP方式の実装考慮点</p><p>セキュリティ面では以下を考慮する。</p><ul><li>安全な乱数生成器を用いる（信頼できるサードパーティ製のライブラリを用いる）</li><li>桁数は最低でも6桁を推奨</li><li>一度認証に成功したコードの再利用を不可にする</li><li>コードは短期間（例：5～10分）で無効化する</li><li>同じユーザーに対する試行回数を制限する（例：3回失敗でそのコードを無効化し、再発行を促す）</li><li>SMS送信のレートリミットをかけ、余計な送信コストを発生させないようにする（≒ SMSボム攻撃への対応を講ずる）</li><li>SMS本文に 「●●（サービス名）の認証コードです。このコードを他人と共有しないでください」といった情報を含め、フィッシング詐欺から守る工夫をする</li></ul></div><div class="tip custom-block"><p class="custom-block-title">マジックリンク方式の実装考慮点</p><p>マジックリンクに含まれるトークンは、OTP方式のコードと同様の対応を取る。また、以下の点に気をつける。</p><ul><li>HTTPヘッダーで <code>Referrer-Policy: strict-origin-when-cross-origin</code> を設定する <ul><li>マジックリンクをクリックして認証された後、ユーザーがサイト上の外部リンクをクリックすると、マジックリンクのURL（＝トークン）がRefererヘッダーとして遷移先サイトへ漏洩する危険があるため</li></ul></li></ul></div><h2 id="smsコスト管理" tabindex="-1">SMSコスト管理 <a class="header-anchor" href="#smsコスト管理" aria-label="Permalink to &quot;SMSコスト管理&quot;">​</a></h2><p>SMSはメールに比べて運用費用が高いため、コスト管理を重視すべきである。</p><p>推奨は以下の通り。</p><ul><li>SMSではなくメールやアプリ通知などで代替できないかを検討する</li><li>1通あたりの単価と想定送信数を基に、SMS利用の予算計画を立てる</li><li>送信サービスのダッシュボードで実績値を継続的に監視し、予算超過や送信通数の急増を知らせるアラートを設定する</li><li>開発・検証環境では、SMSのモック化やサンプリング（許可された特定の電話番号にのみ送信を制限）を検討する</li></ul><h2 id="smsサービスの選定" tabindex="-1">SMSサービスの選定 <a class="header-anchor" href="#smsサービスの選定" aria-label="Permalink to &quot;SMSサービスの選定&quot;">​</a></h2><p>SMSの配信経路は、大きく分けて以下の2種類に分類される。</p><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">（1）国際網ゲートウェイ</th><th style="text-align:left;">（2）国内直収ゲートウェイ</th></tr></thead><tbody><tr><td style="text-align:left;">説明</td><td style="text-align:left;">海外の通信網を経由して、国内携帯キャリア網に接続される経路</td><td style="text-align:left;">日本のSMS送信事業者が、国内携帯キャリアの設備と直接接続してSMSを配信する経路</td></tr><tr><td style="text-align:left;">到達率</td><td style="text-align:left;">⚠️不安定（キャリアによるブロックがされやすい）</td><td style="text-align:left;">✅️非常に高い</td></tr><tr><td style="text-align:left;">コスト（1通あたり）</td><td style="text-align:left;">✅️安価</td><td style="text-align:left;">⚠️やや高価</td></tr><tr><td style="text-align:left;">送信者IDの設定</td><td style="text-align:left;">⚠️制限あり（多くは数字の羅列）</td><td style="text-align:left;">✅️柔軟（サービス名を英数字で設定可）</td></tr><tr><td style="text-align:left;">配信速度</td><td style="text-align:left;">⚠️不安定な場合あり</td><td style="text-align:left;">✅️高速・安定</td></tr></tbody></table><p>推奨は以下の通り。</p><ul><li>原則、（2）を選択する（コストよりも到達の確実性を優先する） <ul><li>特に本人認証や重大な通知などのクリティカルな用途では、メッセージ不達は致命的であるため</li><li>送信者IDをサービス名にすることで、ユーザーが安心してSMSを開ける（ユーザー体験を向上できる）</li><li>不達によるビジネス上の機会損失や、SMSが届かないといった問い合わせコストを防ぐため</li></ul></li><li>キャリアが定める送信ルール（例：1日の上限数）を遵守する</li></ul>`,39))])}const f=e(r,[["render",p]]);export{k as __pageData,f as default};
